import { createSignal, JSX, type Component } from "solid-js";

import { Button } from "../components/button";

const [theNumber, setTheNumber] = createSignal(32);

// In this example we passthrough div props to the outer div (like class)
export const SimpleBinding: Component<JSX.HTMLAttributes<HTMLDivElement>> = (props) => {
	return (
		<div
			{...props}
			class={`flex flex-row ${props.class}`}
		>
			<Button
				class="size-6 m-2"
				onActivate={() => setTheNumber((n) => n - 1)}
			>
				-
			</Button>
			<span class="text-base my-2">The number is {theNumber()}</span>
			<Button
				class="size-6 m-2"
				onActivate={() => setTheNumber((n) => n + 1)}
			>
				+
			</Button>
		</div>
	);
};
